CREATE TABLE "UserMfa" ("userId" TEXT NOT NULL PRIMARY KEY,"secretCiphertext" TEXT,"pendingSecretCiphertext" TEXT,"pendingExpiresAt" TIMESTAMP(3),"enabledAt" TIMESTAMP(3),"lastUsedStep" BIGINT,"recoveryHashes" JSONB NOT NULL DEFAULT '[]',"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "UserMfa_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "PasswordResetToken" ("id" TEXT NOT NULL PRIMARY KEY,"userId" TEXT NOT NULL,"tokenHash" TEXT NOT NULL,"expiresAt" TIMESTAMP(3) NOT NULL,"usedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "PasswordResetToken_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE UNIQUE INDEX "PasswordResetToken_tokenHash_key" ON "PasswordResetToken"("tokenHash");
CREATE INDEX "PasswordResetToken_userId_expiresAt_idx" ON "PasswordResetToken"("userId","expiresAt");
